-- Differential test against fixtures/reference-vectors.json (generated by the
-- independent Python reference implementation). For every vector:
--   * the Lua verifier accepts the full identifier,
--   * the Lua generator reproduces the Python check character(s),
--   * every other value at the check position is rejected.
return function(T)
  T.suite("reference_vectors")
  local cs = require("pii.checksums")
  local fx = T.load_fixture("reference-vectors.json")
  local east, se, west = cs.east_asia, cs.southeast_asia, cs.west_central_asia

  -- generator per algorithm: returns the Lua-computed check string for a vector
  local GEN = {
    cn_resident_id_mod11_2 = function(v) return east.cn_resident_id_mod11_2.check_character(v.body) end,
    cn_uscc_mod31 = function(v) return east.cn_uscc_mod31.check_character(v.body) end,
    th_mod11 = function(v) return se.th_mod11.check_digit(v.body) end,
    jp_mynumber = function(v) return east.jp_mynumber.check_digit(v.body) end,
    jp_corporate_number = function(v) return east.jp_corporate_number.check_digit(v.body) end,
    kz_iin = function(v) return west.kz_iin.check_digit(v.body) end,
    luhn = function(v) return cs.luhn.check_digit(v.body) end,
    iban_mod97 = function(v) return cs.iban.check_digits(v.country, v.bban) end,
    icao9303_check_digit = function(v) return cs.icao9303.check_digit(v.body) end,
    verhoeff = function(v) return cs.verhoeff.check_digit(v.body) end,
    tr_tckn = function(v) local f = west.tr_tckn.complete(v.body); return f and string.sub(f, 10, 11) or nil end,
    tr_vkn = function(v) return west.tr_vkn.check_digit(v.body) end,
    sg_nric_fin_reconstructed = function(v) return se.sg_nric_fin_reconstructed.check_letter(v.prefix, string.sub(v.body, 2, 8)) end,
    tw_citizen_new_ui = function(v) return east.tw_citizen_new_ui.check_digit(v.body) end,
    hkid_mod11 = function(v) return east.hkid_mod11.check_character(v.body) end,
    ir_national_mod11 = function(v) return west.ir_national_mod11.check_digit(v.body) end,
    kr_rrn_legacy = function(v) return east.kr_rrn_legacy.check_digit(v.body) end,
  }

  local function with_check(aid, v, chk)
    if aid == "jp_corporate_number" then return chk .. v.body end
    if aid == "iban_mod97" then return v.country .. chk .. v.bban end
    return v.body .. chk
  end

  local algos = {}
  for aid in pairs(fx.algorithms) do algos[#algos + 1] = aid end
  table.sort(algos)

  for _, aid in ipairs(algos) do
    local set = fx.algorithms[aid]
    local json = require("pii.json")
    T.case(aid .. ": verify accepts all " .. set.count .. " Python-generated vectors", function()
      for _, v in ipairs(set.vectors) do
        if v.full ~= json.null then
          local ok, why = cs.verify(aid, v.full)
          T.check(ok == true, aid .. " should accept " .. tostring(v.full) .. " (" .. tostring(why) .. ")")
        end
      end
    end)

    T.case(aid .. ": Lua generator reproduces Python check characters", function()
      for _, v in ipairs(set.vectors) do
        local got = GEN[aid](v)
        if v.check == json.null then
          T.eq(got, nil, aid .. " body " .. v.body .. " has no valid check digit")
        else
          T.eq(got, v.check, aid .. " check for " .. tostring(v.body or (v.country .. v.bban)))
        end
      end
    end)

    T.case(aid .. ": every other value at the check position is rejected", function()
      local pos, alphabet = set.check_position, set.check_alphabet
      for _, v in ipairs(set.vectors) do
        if v.check == json.null then
          for d = 0, 9 do
            local ok, why = cs.verify(aid, v.body .. tostring(d))
            T.check(ok == false and why == "no_valid_check_digit", aid .. " no digit valid for " .. v.body)
          end
        elseif pos == "last" or pos == "first" then
          for i = 1, #alphabet do
            local c = string.sub(alphabet, i, i)
            if c ~= v.check then
              local ok = cs.verify(aid, with_check(aid, v, c))
              T.check(ok == false, aid .. " must reject check " .. c .. " for " .. tostring(v.body))
            end
          end
        elseif pos == "3-4" then
          for n = 0, 99 do
            local c = string.format("%02d", n)
            if c ~= v.check then
              local ok = cs.verify(aid, with_check(aid, v, c))
              T.check(ok == false, aid .. " must reject check digits " .. c .. " for " .. v.country .. v.bban)
            end
          end
        elseif pos == "last2" then
          for n = 0, 99 do
            local c = string.format("%02d", n)
            if c ~= v.check then
              local ok = cs.verify(aid, v.body .. c)
              T.check(ok == false, aid .. " must reject " .. c .. " for " .. v.body)
            end
          end
        else
          error("unknown check_position " .. tostring(pos))
        end
      end
    end)
  end

  T.case("reference vector file covers every registered algorithm", function()
    for _, id in ipairs(cs.ids()) do
      T.check(fx.algorithms[id] ~= nil, "vectors exist for " .. id)
    end
  end)
end
